<script setup lang="ts">
import { ref, watch } from 'vue'
import SceneDimensionsFields from './SceneDimensionsFields.vue'
import type { Rect, Layer, Scene } from '../tabletop/types'
const props=defineProps<{scene:Scene;target:{id:string;name:string;rect:Rect;layer:Layer}|null;busy:boolean;error:string;remove:(id:string)=>Promise<boolean>;save:(id:string,rect:Rect,layer:Layer,sceneSize?:{width:number;height:number;cell_size:number})=>Promise<boolean>}>()
const emit=defineEmits<{close:[]}>()
const sceneWidth=ref(props.scene.width),sceneHeight=ref(props.scene.height),sceneCell=ref(props.scene.cell_size)
const rotation=ref(0)
const x=ref(0),y=ref(0),width=ref(100),height=ref(100),layer=ref<Layer>('fundo'),ratio=ref(true)
let aspect=1
watch(()=>props.target,target=>{if(target){ratio.value=true;sceneWidth.value=props.scene.width;sceneHeight.value=props.scene.height;sceneCell.value=props.scene.cell_size;rotation.value=target.rect.rotation??0;x.value=target.rect.x;y.value=target.rect.y;width.value=target.rect.width;height.value=target.rect.height;layer.value=target.layer;aspect=width.value/height.value}},{immediate:true})
function resize(axis:string){if(ratio.value){if(axis==='width')height.value=Math.round(Number(width.value)/aspect);else width.value=Math.round(Number(height.value)*aspect)}}
async function save(){if(props.target&&await props.save(props.target.id,{x:Number(x.value),y:Number(y.value),width:Number(width.value),height:Number(height.value),rotation:Number(rotation.value)},layer.value,props.target.layer==='fundo'?{width:Number(sceneWidth.value),height:Number(sceneHeight.value),cell_size:Number(sceneCell.value)}:undefined))emit('close')}
async function remove(){if(props.target&&props.target.id!=='background'&&await props.remove(props.target.id))emit('close')}
function fitScene(){width.value=Math.round(Number(width.value));height.value=Math.round(Number(height.value));sceneWidth.value=width.value;sceneHeight.value=height.value;x.value=0;y.value=0}
</script>
<template><q-dialog :model-value="!!target" :persistent="busy" @update:model-value="emit('close')"><q-card class="modal transform-dialog"><q-card-section><span class="eyebrow">POSIÇÃO E TAMANHO</span><h2>Redimensionar imagem</h2><p>{{ target?.name }}</p><form @submit.prevent="save"><template v-if="target?.layer === 'fundo'"><SceneDimensionsFields :width="sceneWidth" :height="sceneHeight" :cell="sceneCell" :disabled="busy" @change="sceneWidth=$event.width;sceneHeight=$event.height;sceneCell=$event.cell" /><button type="button" class="text-button" :disabled="busy" @click="fitScene">Ajustar cenário ao tamanho da imagem</button></template><p v-else class="dimensions-summary">Cenário: {{ scene.width }} × {{ scene.height }} pixels</p><div class="rect-fields"><label>Posição X<input v-model="x" type="number" min="0" :max="sceneWidth - Number(width)" step="any" required></label><label>Posição Y<input v-model="y" type="number" min="0" :max="sceneHeight - Number(height)" step="any" required></label><label>Largura (pixels)<input v-model="width" type="number" min="8" :max="sceneWidth - Number(x)" step="any" required @change="resize('width')"></label><label>Altura (pixels)<input v-model="height" type="number" min="8" :max="sceneHeight - Number(y)" step="any" required @change="resize('height')"></label><label>Rotação (graus)<input v-model="rotation" type="number" step="any" required></label></div><label class="table-checkbox"><input v-model="ratio" type="checkbox"> Manter proporção</label><template v-if="target?.id !== 'background'"><label for="image-layer">Camada da imagem</label><select id="image-layer" v-model="layer"><option value="fundo">Fundo</option><option value="mestre">Mestre (oculta dos jogadores)</option><option value="geral">Geral</option></select></template><p v-if="error" role="alert" class="scene-upload-error">{{ error }}</p><div class="modal-actions"><button v-if="target?.id !== 'background'" type="button" class="delete-object" :disabled="busy" @click="remove">Excluir objeto</button><button type="button" class="text-button" :disabled="busy" @click="emit('close')">Cancelar</button><button class="primary" :disabled="busy">Salvar dimensões</button></div></form></q-card-section></q-card></q-dialog></template>
<style scoped>.delete-object{margin-right:auto;border:1px solid #a34a63;background:#542738;color:#ffd1df;border-radius:7px;padding:10px}.rect-fields{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.transform-dialog select{width:100%;padding:12px;color:#eadff3;background:#17111e;border:1px solid #59436a;border-radius:7px}.scene-upload-error{color:#ffc0d0}.transform-dialog input[type=checkbox]{width:auto}.dimensions-summary{font-size:11px;color:#a98cbe}</style>
